    vector<int> dp(totalStates, -1);
    vector<int> tempDp(totalStates, -1);
    vector<int> arrA(m, 1);
    vector<int> arrB(m);
    dp[encode(arrA, m)] = 0;
    while (n-- > 0) {
        fill(tempDp.begin(), tempDp.end(), -1);
        for (int stateIdx = 0; stateIdx < totalStates; stateIdx++) {
            if (dp[stateIdx] < 0) continue;
            decode(arrA, m, stateIdx, 3);
            for (int mask = 0; mask < (1 << m); mask++) {
                decode(arrB, m, mask, 2);
                bool invalid = false;
                for (int j = 0; j < m; j++) {
                    if (arrA[j] == 0 && arrB[j] == 0) {
                        invalid = true;
                        break;
                    }
                }
                if (invalid) continue;
                int countOnes = 0;
                for (int j = 0; j < m; j++) {
                    if (arrB[j] == 1) {
                        arrB[j] = 2;
                        countOnes++;
                    }
                }
                for (int j = 0; j < m; j++) {
                    if (arrB[j] == 0 && (arrA[j] == 2 || (j > 0 && arrB[j - 1] == 2) || (j + 1 < m && arrB[j + 1] == 2))) {
                        arrB[j] = 1;
                    }
                }
                int newIdx = encode(arrB, m);
                tempDp[newIdx] = max(tempDp[newIdx], dp[stateIdx] + m - countOnes);
            }
        }
        swap(dp, tempDp);
    }
    int maxVal = 0;
    for (int idx = 0; idx < totalStates; idx++) {
        if (dp[idx] <= maxVal) continue;
        vector<int> arrA_local(m);
        decode(arrA_local, m, idx, 3);
        bool bad = false;
        for (int j = 0; j < m; j++) {
            if (arrA_local[j] == 0) {
                bad = true;
                break;
            }
        }
        if (!bad) maxVal = dp[idx];
    }
    cout << maxVal << "\n";
    return 0;
}

